import{_ as a}from"./chunks/synth_basic.4aC2mAaW.js";import{_ as t,o as s,c as o,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const f=JSON.parse('{"title":"Basic","description":"","frontmatter":{},"headers":[],"relativePath":"synths/engines/BASIC.md","filePath":"synths/engines/BASIC.md"}'),i={name:"synths/engines/BASIC.md"};function r(h,e,l,c,d,p){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="basic" tabindex="-1">Basic <a class="header-anchor" href="#basic" aria-label="Permalink to &quot;Basic&quot;">​</a></h1><p>Basic is the plainest of the synths: one oscillator, a Square, Saw, Sine, Triangle or Pulse wave, given a Detune in cents, a Fine from −10.0 to +10.0 cents in tenths, and a Level, through snappy ADSR envelopes and a ladder filter each note&#39;s own. It is the quickest way to hear what one wave sounds like through the filter and the envelopes; for several oscillators beating against each other, the thick lead and the bass with weight, use <a href="./ASHEVILLE">Asheville</a>.</p><p><img src="'+a+'" alt="The Oscillators tab of Basic"></p><h2 id="how-basic-is-built" tabindex="-1">How Basic Is Built <a class="header-anchor" href="#how-basic-is-built" aria-label="Permalink to &quot;How Basic Is Built&quot;">​</a></h2><p>Each oscillator works out its wave every sample from where it is in its cycle. A naive saw or square holds harmonics far above what a sample rate can carry, and they fold back down as harsh, out-of-tune whistles; so each jump of the saw, the square and the pulse is smoothed over the four samples around it by a polyBLEP, a small correction that takes away the folding, and each corner of the triangle is rounded over the same four samples by its partner, a polyBLAMP, while the sine needs nothing. The waves stay full and bright at every pitch, with no octave tables and no change of tone from one octave to the next, and they stay clean wherever the pitch goes, under glide, vibrato and audio-rate FM. The pulse&#39;s width can move smoothly, as the Mod Matrix&#39;s Pulse width moves it.</p><p>The oscillator&#39;s read speed is worked out from the pitch and the detune once, and again only when something moves the pitch, so that a held note costs a few operations a sample. The Mod Matrix&#39;s Detune moves the oscillator by its Detune, so that a route can bend it away from the note and back.</p>',6)])])}const w=t(i,[["render",r]]);export{f as __pageData,w as default};
